import './usage-rules.js';
const Rules=globalThis.MobUsageRules;
export function createFlowControls({document:doc,snapshot,settings,save,modal,close}){
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const modes={permanent:'Block permanently',schedule:'Block on a schedule',daily:'Set a daily usage limit',session:'Set a session limit',focus:'Block during Pomodoro focus'};
 let selected=new Map(),editing;
 const duration=n=>[Math.floor(n/3600)&&Math.floor(n/3600)+"h",Math.floor(n/60)%60&&Math.floor(n/60)%60+"m",n%60&&n%60+"s"].filter(Boolean).join(" ");
 function rules(){const value=settings(),all=[...(value.usageRules||[])];
  if(value.dailyLimit>0)all.push({id:'legacy-youtube',name:'YouTube daily limit',mode:'daily',minutes:value.dailyLimit,items:[{kind:'website',label:'youtube.com'}]});
  for(const [domain,minutes] of Object.entries(value.siteLimits||{}))all.push({id:'legacy-'+domain,name:domain+' daily limit',mode:'daily',minutes,items:[{kind:'website',label:domain}]});
  if(value.blockedSites?.length)all.push({id:'legacy-focus',name:'Focus block list',mode:'focus',items:value.blockedSites.map(label=>({kind:'website',label}))});return Rules.clean(all);}
 function catalog(){const values=new Map();for(const item of snapshot().catalog||[])if(['app','website'].includes(item.kind))values.set(Rules.key(item),item);for(const rule of rules())for(const item of rule.items)values.set(Rules.key(item),item);return [...values.values()].filter(i=>!['mob','usemob.netlify.app','mob-focus-test-nov19.candidleopard2.chatgpt.site','mob-focus-north.autumnalaspen.chatgpt.site'].includes(i.label.toLowerCase())).sort((a,b)=>a.label.localeCompare(b.label));}
 function render(){const activeRules=rules();return `<section class="card usage-rule-card"><div class="card-header"><div><h2>Usage limits & focus blocking</h2></div><button class="button primary" data-rule-action="new">Add limit</button></div><div class="usage-rules">${activeRules.map(r=>`<article class="usage-rule"><div><strong>${escape(r.name)}</strong><small>${modes[r.mode]}${['daily','session'].includes(r.mode)?' · '+duration(r.seconds||r.minutes*60):''} · ${r.items.length} selected</small><p>${r.items.map(i=>escape(i.label)).join(', ')}</p></div><label class="switch"><input type="checkbox" data-rule-toggle="${escape(r.id)}" ${r.enabled?'checked':''} aria-label="Enable ${escape(r.name)}"></label><button class="text-action" data-rule-action="edit" data-id="${escape(r.id)}">Edit</button></article>`).join('')||'<p class="empty">No limits yet.</p>'}</div></section>`;}
 function pickerList(){const daily=snapshot().daily;const box=doc.querySelector('#rule-items');if(!box)return;const term=(doc.querySelector('#rule-search')?.value||'').toLowerCase(),filter=doc.querySelector('#rule-kind')?.value||'all';box.innerHTML=catalog().filter(i=>(filter==='all'||i.kind===filter)&&i.label.toLowerCase().includes(term)).map(i=>`<label class="rule-choice"><input type="checkbox" data-rule-item="${escape(Rules.key(i))}" ${selected.has(Rules.key(i))?'checked':''}><span><strong>${escape(i.label)}</strong><small>${i.kind==='website'?'Website':'Desktop app'} · ${duration(daily[Rules.key(i)]||0) || '0s'} today (UTC)</small></span></label>`).join('')||'<p class="small-text muted">No matching visited items yet. Link the extension for websites and enable foreground tracking for apps.</p>';}
 function edit(id,item){editing=rules().find(r=>r.id===id);selected=new Map((editing?.items||item&&[item]||[]).map(i=>[Rules.key(i),i]));
 modal(editing?'Edit usage limit':'Create a usage limit',`<form id="usage-rule-form" class="dialog-body"><details class="usage-item-picker" open><summary>Select websites and apps to limit (<span id="rule-count">${selected.size}</span>)</summary><div class="rule-picker-tools"><input id="rule-search" type="search" placeholder="Search visited apps and websites" aria-label="Search visited apps and websites"><select id="rule-kind" aria-label="Item type"><option value="all">Apps & websites</option><option value="website">Websites</option><option value="app">Desktop apps</option></select></div><div class="rule-picker-buttons"><button class="text-action" type="button" data-rule-action="select-visible">Select shown</button><button class="text-action" type="button" data-rule-action="clear-selection">Clear selection</button></div><div id="rule-items" class="rule-items"></div></details><fieldset class="rule-modes"><legend>How do you want to limit the selected items?</legend>${Object.entries(modes).map(([value,label])=>`<label><input type="radio" name="mode" value="${value}" ${(editing?.mode||'daily')===value?'checked':''}>${label}</label>`).join('')}</fieldset><div id="rule-duration"><div class="duration-fields"><label class="field">Hours<input name="hours" type="number" min="0" max="24" step="1" value="${Math.floor((editing?.seconds||1800)/3600)}"></label><label class="field">Minutes<input name="minutes" type="number" min="0" max="59" step="1" value="${Math.floor((editing?.seconds||1800)/60)%60}"></label><label class="field">Seconds<input name="seconds" type="number" min="0" max="59" step="1" value="${(editing?.seconds||1800)%60}"></label></div><small class="muted">Choose from 1 second to 24 hours. Enforcement follows the tracker's sampling interval.</small></div><div id="rule-schedule"><div class="form-grid"><label class="field">From<input name="start" type="time" value="${editing?.start||'09:00'}"></label><label class="field">Until<input name="end" type="time" value="${editing?.end||'17:00'}"></label></div><div class="rule-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,n)=>`<label><input type="checkbox" name="days" value="${n}" ${(editing?.days||[1,2,3,4,5]).includes(n)?'checked':''}>${day}</label>`).join('')}</div></div><label class="field">Limit name (optional)<input name="name" maxlength="60" placeholder="e.g. Quiet work mornings" value="${escape(editing?.name||'')}"></label><p class="error" role="alert"></p><div class="form-actions">${editing?'<button class="button danger" type="button" data-rule-action="delete">Delete limit</button>':''}<button class="button" type="button" data-rule-action="cancel">Cancel</button><button class="button primary" type="submit">Save limit</button></div></form>`);pickerList();fields();}
 function fields(){const mode=doc.querySelector('#usage-rule-form input[name="mode"]:checked')?.value;const duration=doc.querySelector('#rule-duration'),schedule=doc.querySelector('#rule-schedule');if(duration)duration.hidden=!['daily','session'].includes(mode);if(schedule)schedule.hidden=mode!=='schedule';}
 function update(value){save({usageRules:Rules.clean(value),dailyLimit:0,siteLimits:{},blockedSites:[]});}
 doc.addEventListener('click',e=>{const target=e.target.closest('[data-rule-action]');if(!target)return;e.preventDefault();const action=target.dataset.ruleAction;
  if(action==='new')edit();if(action==='edit')edit(target.dataset.id);
  if(action==='limit-item'){const at=target.dataset.id.indexOf(':');edit(null,{kind:target.dataset.id.slice(0,at)==='website'?'website':'app',label:target.dataset.id.slice(at+1)});}
  if(action==='cancel')close();if(action==='delete'){update(rules().filter(r=>r.id!==editing.id));close();}
  if(action==='select-visible'){for(const input of doc.querySelectorAll('[data-rule-item]')){const item=catalog().find(i=>Rules.key(i)===input.dataset.ruleItem);if(item)selected.set(Rules.key(item),item);}pickerList();}
  if(action==='clear-selection'){selected.clear();pickerList();}const count=doc.querySelector('#rule-count');if(count)count.textContent=selected.size;
 });
 doc.addEventListener('input',e=>{if(e.target.id==='rule-search')pickerList();});
 doc.addEventListener('change',e=>{if(e.target.id==='rule-kind')pickerList();if(e.target.name==='mode')fields();if(e.target.dataset.ruleItem){const item=catalog().find(i=>Rules.key(i)===e.target.dataset.ruleItem);if(item){if(e.target.checked)selected.set(Rules.key(item),item);else selected.delete(Rules.key(item));}doc.querySelector('#rule-count').textContent=selected.size;}if(e.target.dataset.ruleToggle)update(rules().map(r=>r.id===e.target.dataset.ruleToggle?{...r,enabled:e.target.checked}:r));});
 doc.addEventListener('submit',e=>{if(e.target.id!=='usage-rule-form')return;e.preventDefault();const form=e.target,values=new doc.defaultView.FormData(form),mode=values.get('mode');if(!selected.size){form.querySelector('.error').textContent='Select at least one visited app or website.';return;}const seconds=Number(values.get('hours'))*3600+Number(values.get('minutes'))*60+Number(values.get('seconds'));if(['daily','session'].includes(mode)&&(!Number.isInteger(seconds)||seconds<1||seconds>86400)){form.querySelector('.error').textContent='Choose a duration from 1 second to 24 hours.';return;}const rule={id:editing?.id||crypto.randomUUID(),enabled:editing?.enabled??true,name:values.get('name')||modes[mode],mode,seconds,minutes:seconds/60,start:values.get('start'),end:values.get('end'),days:values.getAll('days').map(Number),items:[...selected.values()]};if(mode==='schedule'&&!rule.days.length){form.querySelector('.error').textContent='Select at least one schedule day.';return;}const next=[...rules().filter(r=>r.id!==rule.id),rule];if(new TextEncoder().encode(JSON.stringify(next)).length>20000){form.querySelector(".error").textContent="This rule list is full. Reduce the number of selections.";return;}update(next);close();});
 return {render,edit};
}
